package com.shazwan.idash;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import android.text.*;import java.io.*;import java.text.*;import java.util.*;import java.util.concurrent.*;
/** Controlled clock boundaries, isolated offline cache and real Activity recreation. */
public class QualityChecks extends Instrumentation {
 LauncherActivity a;SharedPreferences prefs;Map<String,?> saved;Locale locale;TimeZone zone;int count;StringBuilder notes=new StringBuilder();
 void check(boolean ok,String name){if(!ok)throw new AssertionError(name);count++;}
 void ui(Runnable work){Throwable[] error={null};runOnMainSync(()->{try{work.run();}catch(Throwable t){error[0]=t;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 void ready()throws Exception{CountDownLatch latch=new CountDownLatch(1);a.worker.execute(()->a.main.post(latch::countDown));check(latch.await(45,TimeUnit.SECONDS),"worker ready");waitForIdleSync();}
 long at(String value)throws Exception{SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.US);f.setTimeZone(JakimCalendar.MY);return f.parse(value).getTime();}
 String expected(String pattern,long at){return new SimpleDateFormat(pattern,Locale.getDefault()).format(new Date(at));}
 boolean tickerPending(){StringBuilder queue=new StringBuilder();a.main.dump(s->queue.append(s).append('\n'),"");return java.util.regex.Pattern.compile(java.util.regex.Pattern.quote(a.ticker.getClass().getName())+"(?:\\s|@|\\})").matcher(queue).find();}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;File sandbox=null;try{
  prefs=getTargetContext().getSharedPreferences("idash",0);saved=new HashMap<>(prefs.getAll());locale=Locale.getDefault();zone=TimeZone.getDefault();Locale.setDefault(Locale.US);TimeZone.setDefault(JakimCalendar.MY);
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();ui(()->{a.main.removeCallbacks(a.ticker);prefs.edit().putBoolean("calendar",true).putBoolean("jakim",true).putBoolean("prayer_countdown",true).putBoolean("24h",true).apply();a.page="home";a.panelVisible=false;a.setJakimZone("SGR02");a.render();a.main.removeCallbacks(a.ticker);});ready();
  long before=at("2026-11-02 23:59:30"),after=at("2026-11-03 00:00:01");
  ui(()->{a.updateClock(before);check("23:59".contentEquals(a.clock.getText()),"24h before midnight");check(a.date.getText().toString().equals(expected("EEEE, d MMMM",before)),"clock date before midnight");check(a.calendarDay.getText().toString().equals(a.date.getText().toString()),"calendar synchronized before midnight");a.updateClock(after);check("00:00".contentEquals(a.clock.getText()),"clock crosses midnight");check(a.date.getText().toString().equals(expected("EEEE, d MMMM",after)),"clock date rolls day");check(a.calendarDay.getText().toString().equals(a.date.getText().toString()),"calendar rolls day without render");check("2026-11-03".equals(a.jakimDayKey),"JAKIM MYT day rolls");JakimCalendar.Day day=a.jakimDays.get("2026-11-03");for(String time:day.times)check(a.jakimText.getText().toString().contains(time),"official new-day times");check(a.jakimNext.getText().toString().startsWith("Subuh"),"next prayer after midnight");
   final int[] writes={0};TextWatcher watcher=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int n){}public void onTextChanged(CharSequence s,int st,int b,int c){}public void afterTextChanged(Editable e){writes[0]++;}};TextView[] views={a.clock,a.date,a.calendarDay,a.statusTime,a.jakimText,a.jakimNext};for(TextView v:views)v.addTextChangedListener(watcher);for(int n=0;n<60;n++){a.updateClock(after+n*500);a.updateJakim(after);}check(writes[0]==0,"same minute/text does not rewrite labels");for(TextView v:views)v.removeTextChangedListener(watcher);
   prefs.edit().putBoolean("24h",false).apply();a.updateClock(after);check(a.clock.getText().toString().equals(expected("h:mm a",after)),"12h preference refreshes same minute");Locale.setDefault(Locale.forLanguageTag("ms-MY"));a.updateClock(after);check(a.calendarDay.getText().toString().equals(expected("EEEE, d MMMM",after)),"locale refreshes same minute");TimeZone.setDefault(TimeZone.getTimeZone("UTC"));a.updateClock(after);check(a.clock.getText().toString().equals(expected("h:mm a",after)),"time zone refreshes same minute");check(a.jakimDayKey.equals("2026-11-03"),"JAKIM stays MYT when local timezone differs");});
  check(JakimCalendar.nextPrayer(a.jakimDays,at("2026-11-03 06:00:00")).startsWith("Zohor"),"sunrise is not next obligatory prayer");check(JakimCalendar.nextPrayer(a.jakimDays,at("2026-11-03 23:59:00")).startsWith("Subuh"),"next-day timetable used after Isyak");long missing=at("2027-01-01 00:00:01");ui(()->{a.updateClock(missing);check(a.jakimText.getText().toString().contains("Tiada jadual"),"missing year never reuses expired timetable");});
  sandbox=new File(a.getFilesDir(),"quality-cache-fixture");sandbox.mkdirs();final File own=sandbox;Context isolated=new ContextWrapper(getTargetContext()){@Override public File getFilesDir(){return own;}};
  for(String z:JakimCalendar.ZONES){Map<String,JakimCalendar.Day> days=JakimCalendar.load(isolated,z);check(days.size()==365,"offline official cache "+z);check(days.containsKey("2026-11-03"),"offline current row "+z);check(!days.containsKey("2027-11-03"),"offline no fabricated coverage "+z);}
  File file=new File(sandbox,"jakim-SGR02.json");try(Writer out=new FileWriter(file)){out.write("invalid JSON");}check(JakimCalendar.load(isolated,"SGR02").size()==365,"corrupt cache preserves bundled valid data");check(JakimCalendar.load(isolated,"../../bad").isEmpty(),"invalid zone rejected");
  for(String z:new String[]{"WLY01","SGR02"}){ui(()->a.setJakimZone(z));ready();ui(()->check(a.loadedZone.equals(z)&&a.jakimText.getText().toString().contains(z),"actual zone selection "+z));}
  ui(()->{a.onResume();check(tickerPending(),"resume schedules one ticker");a.onPause();check(!tickerPending(),"pause removes ticker");a.onResume();a.onStop();check(!tickerPending(),"stop removes ticker");a.onStart();a.onResume();a.main.removeCallbacks(a.ticker);});
  Locale.setDefault(locale);TimeZone.setDefault(zone);LauncherActivity old=a;ActivityMonitor monitor=addMonitor(LauncherActivity.class.getName(),null,false);ui(a::recreate);Activity next=monitor.waitForActivityWithTimeout(45000);removeMonitor(monitor);check(next instanceof LauncherActivity,"actual Activity recreation");a=(LauncherActivity)next;ready();check(old.isDestroyed()&&old.worker.isShutdown(),"old Activity releases worker on destroy");ui(()->{check("SGR02".equals(a.prefs.getString("jakim_zone","")),"zone survives recreation");check(a.calendarDay!=null&&a.calendarDay.getText().toString().equals(a.date.getText().toString()),"calendar current after recreation");});
  notes.append("GPS: NOT IMPLEMENTED; manual JAKIM zone, no added location permission.\nOffline tests use official bundled data and isolated corrupt-cache fixture; live JAKIM endpoint not certified.\nClock/timezone boundary inputs are controlled test timestamps, not OS clock or head-unit verification.\n");result.putString("stream","PASS: "+count+" clock/cache/lifecycle checks\n"+notes);code=Activity.RESULT_OK;
 }catch(Throwable e){result.putString("stream","FAIL after "+count+": "+e+"\n"+notes);}finally{if(locale!=null)Locale.setDefault(locale);if(zone!=null)TimeZone.setDefault(zone);if(prefs!=null&&saved!=null)AppearanceChecks.restore(prefs,saved);if(a!=null)ui(()->{if(a.quickControls!=null)a.quickControls.close();a.finish();});if(sandbox!=null){File f=new File(sandbox,"jakim-SGR02.json");f.delete();sandbox.delete();}}finish(code,result);}
}
